import { test, expect } from '@playwright/test';

test.describe('Card Payment Flow - Complete Purchase', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully complete purchase with valid card details', async ({ page }) => {
    // Verify checkout page is visible
    const checkoutContainer = page.getByRole('region', { name: /checkout/i });
    await expect(checkoutContainer).toBeVisible();

    // Verify payment form is visible
    const paymentForm = page.getByRole('form', { name: /enter card details/i });
    await expect(paymentForm).toBeVisible();

    // Verify card number input is present
    const cardNumberInput = page.getByLabel(/card number/i);
    await expect(cardNumberInput).toBeVisible();

    // Verify expiration date input is present
    const expirationDateInput = page.getByLabel(/expiration date/i);
    await expect(expirationDateInput).toBeVisible();

    // Verify CVV input is present
    const cvvInput = page.getByLabel(/cvv/i);
    await expect(cvvInput).toBeVisible();

    // Verify submit button is visible
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();

    // Fill in valid card details
    await cardNumberInput.fill('4111111111111111');
    await expirationDateInput.fill('12/25');
    await cvvInput.fill('123');

    // Click submit button
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/purchase successful/i);
    await expect(successMessage).toBeVisible();

    // Verify order confirmation page is displayed
    const orderConfirmation = page.getByRole('region', { name: /order confirmation/i });
    await expect(orderConfirmation).toBeVisible();

    // Verify order details are displayed
    const orderDetails = page.getByText(/order number: 123456789/i);
    await expect(orderDetails).toBeVisible();

    // Verify order summary is displayed
    const orderSummary = page.getByText(/total: $100.00/i);
    await expect(orderSummary).toBeVisible();

    // Verify order button is visible
    const placeOrderButton = page.getByRole('button', { name: /place order/i });
    await expect(placeOrderButton).toBeVisible();

    // Verify order button is enabled
    await expect(placeOrderButton).toBeEnabled();

    // Click place order button
    await placeOrderButton.click();

    // Verify order is placed
    const orderConfirmationMessage = page.getByText(/order placed successfully/i);
    await expect(orderConfirmationMessage).toBeVisible();

    // Verify order confirmation page is still visible
    await expect(orderConfirmation).toBeVisible();
  });

